import React, { useState } from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter, Button, Form, FormGroup, Label, Input } from 'reactstrap';

const ContractModal = ({ isOpen, toggle, userId, refreshProposals }) => {
    const [formData, setFormData] = useState({
        photoUrl: '',
        goodName: '',
        goodDetail: '',
        goodRequire: '',
        term: '',
        payWay: '',
        pay: '',
    });

    const handleChange = (e) => {
        const { name, value } = e.target;
        setFormData({
            ...formData,
            [name]: value,
        });
    };

    const handleFileChange = (e) => {
        setFormData({
            ...formData,
            photoUrl: e.target.files[0],
        });
    };

    const handleSubmit = () => {
        const proposalData = {
            ...formData,
            userId,
        };

        console.log('Submitting proposal:', proposalData); // 로그 추가

        fetch('http://localhost:8080/api/proposals', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify(proposalData),
        })
            .then((response) => response.json())
            .then((data) => {
                console.log('Proposal submitted:', data); // 로그 추가
                toggle(); // 모달을 닫습니다.
                refreshProposals(); // 제안서 목록을 새로고침합니다.
            })
            .catch((error) => {
                console.error('Error:', error);
            });
    };

    return (
        <Modal isOpen={isOpen} toggle={toggle} size="lg">
            <ModalHeader toggle={toggle}>제안서</ModalHeader>
            <ModalBody>
                <Form>
                    <FormGroup>
                        <Label for="photoUrl">제품 사진</Label>
                        <Input type="file" name="photoUrl" id="photoUrl" onChange={handleFileChange} />
                    </FormGroup>
                    <FormGroup>
                        <Label for="goodName">제품 명</Label>
                        <Input
                            type="text"
                            name="goodName"
                            id="goodName"
                            placeholder="ex) 게이밍 마우스"
                            value={formData.goodName}
                            onChange={handleChange}
                        />
                    </FormGroup>
                    <FormGroup>
                        <Label for="goodDetail">제품 설명 (생략 가능)</Label>
                        <Input
                            type="textarea"
                            name="goodDetail"
                            id="goodDetail"
                            placeholder="ex) 그립감 좋고 무소음인 게이밍 마우스"
                            value={formData.goodDetail}
                            onChange={handleChange}
                        />
                    </FormGroup>
                    <FormGroup>
                        <Label for="goodRequire">요구사항</Label>
                        <Input
                            type="textarea"
                            name="goodRequire"
                            id="goodRequire"
                            placeholder="ex) 게시물 사진은 요청 수락하면 총 3장 보내드리겠습니다! \n광고 문구는 조용하고 그립감 편하다는 느낌으로 말해주시면 돼요."
                            value={formData.goodRequire}
                            onChange={handleChange}
                        />
                    </FormGroup>
                    <FormGroup>
                        <Label for="term">업로드 기간</Label>
                        <Input
                            type="text"
                            name="term"
                            id="term"
                            placeholder="ex) 총 3주(21일)"
                            value={formData.term}
                            onChange={handleChange}
                        />
                    </FormGroup>
                    <FormGroup>
                        <Label for="payWay">지급 방법</Label>
                        <Input type="select" name="payWay" id="payWay" value={formData.payWay} onChange={handleChange}>
                            <option>분할 지급</option>
                            <option>선불</option>
                            <option>후불</option>
                        </Input>
                    </FormGroup>
                    <FormGroup>
                        <Label for="pay">총 금액</Label>
                        <Input
                            type="text"
                            name="pay"
                            id="pay"
                            placeholder="ex) 1000,000원"
                            value={formData.pay}
                            onChange={handleChange}
                        />
                    </FormGroup>
                </Form>
            </ModalBody>
            <ModalFooter>
                <Button color="primary" onClick={handleSubmit}>
                    제출
                </Button>
                <Button color="secondary" onClick={toggle}>
                    취소
                </Button>
            </ModalFooter>
        </Modal>
    );
};

export default ContractModal;
